INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT147-S4-Q18$batch02$, 147, 4, 18, $batch02$Flaw$batch02$, $batch02$Pundit: For many high school graduates, attending a university would be of no help in getting a corporate job. The attributes corporations value most in potential employees are initiative, flexibility, and the ability to solve practical problems. Many new high school graduates have these attributes already.$batch02$, $batch02$The pundit’s argument is most vulnerable to criticism on the grounds that it$batch02$, $batch02$B$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=147 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$fails to establish that university graduates do not have initiative, flexibility, and the ability to solve practical problems$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$overlooks the possibility that corporations may require an attribute that potential employees can obtain only by attending a university$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$provides no justification for the presumption that corporations only hire employees who have initiative, flexibility, and the ability to solve practical problems$batch02$, $batch02$Too Strong$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$takes for granted that the only reason that high school graduates go on to attend university is to improve their job prospects$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$takes for granted that initiative, flexibility, and the ability to solve practical problems are attributes that can be acquired through study$batch02$, $batch02$Not Assumed$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$For many high school graduates, university would not help them get a corporate job.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Corporations value initiative, flexibility and practical problem solving *most*, and many graduates already have them.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$"Valued most" is not "the only thing required." A corporation may rank initiative first and still refuse to hire anyone without a degree or specialized knowledge. If university supplies something employers require, it helps even graduates who already have the top three attributes.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for something else corporations want that only university provides.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The pundit need not say university graduates lack these traits. Graduates could have them too; the question is whether university adds anything for people who already have them.$batch02$), ($batch02$B$batch02$, $batch02$If corporations also require an attribute available only through university, such as a credential or specific training, then attending helps get the job. The pundit's evidence covers only the attributes valued *most*, not everything required.$batch02$), ($batch02$C$batch02$, $batch02$The pundit does not need corporations to hire *only* people with these traits. The argument fails because other requirements might exist, not because of how strict these ones are.$batch02$), ($batch02$D$batch02$, $batch02$The conclusion is limited to job prospects. Other reasons for attending university do not bear on it.$batch02$), ($batch02$E$batch02$, $batch02$The pundit points out that many graduates *already* have the traits. Whether study can produce them does not matter for those graduates.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT147-S4-Q18$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
